/// <summary>
/// PricingAttribute of table <c>EcoResProductCategory</c> field Category for level 5 i.e. MET category.
/// </summary>
 [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
 [GUPPricingAttributeFieldsDiscovery(fieldStr(EcoResProductCategory, Category))]
internal class METGUPPricingAttributeEcoResProductCategoryCategory extends METGUPPricingAttributeEcoResProductCategory implements GUPIPricingAttribute
{

}

Method.Source:
/// <summary>
/// Get value of the attribute
/// </summary>
/// <param name="_pricingObject">
/// The <c>Common</c> object that will be used to get the table record
/// </param>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).Category;
}

/// <summary>
/// Retuns the name of the attribute
/// </summary>
public str getName()
{
    return "@MET:METCategory";
}

/// <summary>
/// Get attribte data type
/// </summary>
public AttributeDataType getDataType()
{
    return AttributeDataType::Reference;
}

    /// <summary>
    /// Builds pricing object query
    /// </summary>
    /// <param name="_query">
    /// The <c>Query</c> object that the new ranges will be added to.
    /// </param>
    /// <param name="_value">
    /// The <c>anytype</c> object that determines the category.
    /// </param>
    /// <param name="_qdbsMap">
    /// The <c>Map</c> object that is used to identify the query build data source.
    /// </param>
    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbdsEcoResCategory;

        qbdsEcoResCategory = this.getQueryBuildDatasource(_query, _qdbsMap);

        List recIdList = strSplit(_value, ',');
        ListEnumerator enumerator = recIdList.getEnumerator();
        while (enumerator.moveNext())
        {
            int64 value = any2Int64(enumerator.current());
            EcoResCategory ecoResCategory = EcoResCategory::find(value);
            qbdsEcoResCategory.addRange(fieldNum(EcoResCategory, NestedSetLeft)).value(SysQuery::range(ecoResCategory.NestedSetLeft, ecoResCategory.NestedSetRight));
            qbdsEcoResCategory.addRange(fieldNum(EcoResCategory, NestedSetRight)).value(SysQuery::range(ecoResCategory.NestedSetLeft, ecoResCategory.NestedSetRight));
            qbdsEcoResCategory.addRange(fieldNum(EcoResCategory, CategoryHierarchy)).value(int642Str(ecoResCategory.CategoryHierarchy));
        }
     
        return _query;
    }

    /// <summary>
    /// Gets the reference value of category name
    /// </summary>
    /// <param name="_defaultValue">
    /// The <c>Str</c> default value.
    /// </param>
    public str getRefValue(Str _defaultValue)
    {
        EcoResCategory ecoResCategory;
        str ret = '';
        boolean isFirstAttributeToAppend = true;
        Query query = new Query();
        query.addDataSource(tableNum(EcoResCategory)).addRange(fieldNum(EcoResCategory, RecId)).value(_defaultValue);
        QueryRun qr = new QueryRun(query);

        List priceAttributeValueList = strSplit(_defaultValue, ',');
        ListEnumerator enumerator = priceAttributeValueList.getEnumerator();

        QueryBuildDataSource qbdsEcoResCategory = query.addDataSource(tableNum(EcoResCategory));
        while (enumerator.moveNext())
        {
            qbdsEcoResCategory.addRange(fieldNum(EcoResCategory, RecId)).value(enumerator.current());
        }

        while (qr.next())
        {
            ecoResCategory = qr.get(tableNum(EcoResCategory), 1);
            if (!isFirstAttributeToAppend)
            {
                ret += ',';
            }
            else
            {
                isFirstAttributeToAppend = false;
            }
            ret += ecoResCategory.Name;
        }
        
        return ret;
    }

/// <summary>
/// Validate if the category exists for the default value
/// </summary>
/// <param name="_defaultValue">
/// The <c>Str</c> default vaue which needs to be validated
/// </param>
public boolean validate(Str _defaultValue)
{
    return EcoResCategory::exist(any2Int64(_defaultValue));
}

    /// <summary>
    /// Creates lookup of category hierarchy
    /// </summary>
    /// <param name="_formStringControl">
    /// The <c>object</c> object for which lookup values are allowed
    /// </param>
    public void lookupAllowedValues(object _formStringControl)
    {
        
        SysTableLookup                  sysTableLookup;
        Query                           query;
        QueryBuildDataSource            qbdsEcoResCategory;
        QueryBuildRange                 qbrLevel, qbrHierarchy;
        ProdTable                       prodTable;
        EcoResCategoryHierarchyRole     ecoResCategoryHierarchyRole = EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::Retail);
        ;

        
        if (ecoResCategoryHierarchyRole.RecId)
        {
            sysTableLookup = SysTableLookup::newParameters(tablenum(EcoResCategory), _formStringControl);

            query = new Query();
            qbdsEcoResCategory = query.addDataSource(tableNum(EcoResCategory));
            qbrLevel = qbdsEcoResCategory.addRange(fieldNum(EcoResCategory,Level));
            qbrLevel.value(SysQuery::value(METConstants::CategoryLevel));

            qbrHierarchy = qbdsEcoResCategory.addRange(fieldNum(EcoResCategory,CategoryHierarchy));
            qbrHierarchy.value(SysQuery::value(ecoResCategoryHierarchyRole.CategoryHierarchy));

            sysTableLookup.addLookupfield(fieldnum(EcoResCategory, Name),false);
            sysTableLookup.addLookupfield(fieldnum(EcoResCategory, Level),false);
            sysTableLookup.addLookupfield(fieldnum(EcoResCategory, RecId),true);
       
            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }
        else
        {
            throw Error ("@MET:DefaultRetailCategoryNotFound");
        }
        
    }

/// <summary>
/// Returns true for reference record ID.
/// </summary>
public boolean isRefRecIdValue()
{
    return true;
}
